function a1Tree(){const R=rng(31);let canopy='',leaves='';
 const blobs=[[2120,150,170,110],[2280,40,190,120],[2460,90,200,120],[2620,210,170,105],[2020,270,150,95],[2240,250,170,100],[2420,270,190,105],[2580,340,140,80],[2330,150,210,110],[2120,-20,170,110],[2480,-40,190,110],[2700,90,150,95]];
 blobs.forEach((b,i)=>{const [x,y,rx,ry]=b;canopy+=`<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="url(#ixLeafG)" stroke="#6fa785" stroke-opacity=".45" stroke-width="2"/><ellipse cx="${x-rx*.25}" cy="${y-ry*.35}" rx="${rx*.45}" ry="${ry*.32}" fill="#e1f4e4" opacity=".55"/>`;
  for(let k=0;k<14;k++){const a=Math.PI*(.15+.7*R()),lx=x+Math.cos(a)*rx*(.7+R()*.35)*(R()<.5?-1:1),ly=y+Math.sin(a)*ry*(.75+R()*.3),rot=-25+R()*50,sc=.8+R()*.7;leaves+=`<path d="${leafPath()}" transform="translate(${r2(lx)},${r2(ly)}) rotate(${r2(rot)}) scale(${r2(sc)})" fill="${['#a7d7b3','#92c9a2','#bfe3c6','#86bf98'][k%4]}" stroke="#5f9474" stroke-opacity=".5" stroke-width="1"/>`}});
 const nuts=[[2210,330],[2390,350],[2540,300],[2150,240]].map(n=>`<g transform="translate(${n[0]},${n[1]})"><path d="M0,0 L-8,22 M0,0 L6,24 M0,0 L-1,26" stroke="#8a7a6a" stroke-width="1.5"/><circle cx="-8" cy="26" r="6" fill="#c9b08a"/><circle cx="6" cy="28" r="6" fill="#d6bd96"/><circle cx="-1" cy="31" r="6" fill="#c2a780"/></g>`).join('');
 const trunk='M2232,1046 C2258,1030 2272,1006 2276,972 C2284,890 2288,760 2292,626 C2295,528 2292,446 2284,396 C2254,334 2206,252 2156,150 L2180,140 C2226,226 2270,296 2304,348 C2314,296 2326,176 2330,34 L2356,34 C2358,170 2352,290 2342,354 C2384,302 2432,222 2470,94 L2496,104 C2464,244 2414,334 2376,402 C2370,474 2374,604 2382,764 C2388,884 2396,962 2410,1002 C2426,1032 2470,1048 2516,1056 C2430,1066 2340,1064 2300,1058 C2272,1056 2252,1054 2232,1046 Z';
 let patches='';const pcol=['#ffd8c4','#e8dcf7','#dde8f4','#ffe9c9','#f6d6e6'];
 for(let i=0;i<26;i++){const y=420+R()*600,x=2290+R()*80-30,rw=8+R()*22,rh=20+R()*60;patches+=`<ellipse cx="${r2(x)}" cy="${r2(y)}" rx="${r2(rw)}" ry="${r2(rh)}" fill="${pcol[i%5]}" opacity=".85"/>`}
 for(let i=0;i<10;i++){const t=R();const x=2180+t*130,y=160+t*190;patches+=`<ellipse cx="${r2(x)}" cy="${r2(y)}" rx="7" ry="${r2(14+R()*16)}" fill="${pcol[i%5]}" opacity=".8" transform="rotate(-30 ${r2(x)} ${r2(y)})"/>`}
 return svg('L',`<defs><linearGradient id="ixBark" x1="2260" y1="0" x2="2410" y2="0" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#fffdf7"/><stop offset=".55" stop-color="#f7efe6"/><stop offset="1" stop-color="#e6d6d2"/></linearGradient>
<radialGradient id="ixLeafG" cx="40%" cy="35%" r="75%"><stop offset="0" stop-color="#c9ead0"/><stop offset=".6" stop-color="#a5d6b1"/><stop offset="1" stop-color="#86c296"/></radialGradient><clipPath id="ixTrunkClip"><path d="${trunk}"/></clipPath></defs>
<path d="${trunk}" fill="url(#ixBark)" stroke="${INK}" stroke-opacity=".7" stroke-width="2.6" stroke-linejoin="round"/>
<g clip-path="url(#ixTrunkClip)">${patches}<path d="M2350,1040 C2356,900 2352,700 2346,500" stroke="#d9c4c4" stroke-width="16" opacity=".5" fill="none"/></g>
<path d="M2300,1050 C2250,1056 2190,1050 2150,1040 M2400,1046 C2450,1054 2500,1060 2540,1060" stroke="${INK}" stroke-opacity=".45" stroke-width="2" fill="none"/>
${canopy}${leaves}${nuts}`)}
function a1HoleBack(){return svg('L',`<defs><radialGradient id="ixHoleG" cx="2210" cy="1040" r="160" gradientTransform="translate(0 780) scale(1 .25)" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#1f1426"/><stop offset=".6" stop-color="#3b2734"/><stop offset="1" stop-color="#6e4c45"/></radialGradient>
<radialGradient id="ixSwirl" cx="2210" cy="1046" r="130" gradientTransform="translate(0 784.5) scale(1 .25)" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#ffd1f0" stop-opacity=".55"/><stop offset=".55" stop-color="#b9a0ff" stop-opacity=".18"/><stop offset="1" stop-color="#b9a0ff" stop-opacity="0"/></radialGradient></defs>
<g class="ix-hole">
<path d="M2036,1034 C2040,1000 2110,986 2210,986 C2318,986 2384,1002 2390,1034 C2394,1066 2318,1086 2210,1086 C2100,1086 2032,1066 2036,1034 Z" fill="#c49a76" stroke="${INK}" stroke-opacity=".45" stroke-width="2"/>
<path d="M2052,1032 C2058,1006 2124,996 2210,996 C2300,996 2364,1008 2368,1032 C2372,1056 2300,1072 2210,1072 C2120,1072 2048,1058 2052,1032 Z" fill="#8c6650"/>
<ellipse cx="2210" cy="1040" rx="148" ry="38" fill="url(#ixHoleG)"/>
<path d="M2066,1034 C2100,1010 2320,1010 2354,1034" fill="none" stroke="#d8b28c" stroke-width="5" opacity=".9" stroke-linecap="round"/>
<ellipse class="ix-swirl" cx="2210" cy="1046" rx="124" ry="30" fill="url(#ixSwirl)"/>
<g fill="#a98163" stroke="${INK}" stroke-opacity=".35" stroke-width="1.5"><ellipse cx="2058" cy="1004" rx="16" ry="9"/><ellipse cx="2090" cy="992" rx="11" ry="7"/><ellipse cx="2350" cy="996" rx="14" ry="8"/></g></g>`)}
function a1Lip(){const R=rng(41);let fringe='';
 for(let i=0;i<34;i++){const u=i/33,ang=Math.PI*u,x=2210-150*Math.cos(ang),y=1040+40*Math.sin(ang),h=12+R()*14,lean=(u-.5)*-14;fringe+=`<path d="M${r2(x-4)},${r2(y+4)} Q${r2(x+lean*.4)},${r2(y-h*.5)} ${r2(x+lean)},${r2(y-h)} Q${r2(x+lean*.2+2)},${r2(y-h*.4)} ${r2(x+4)},${r2(y+4)} Z" fill="${['#94d18a','#a7dc98','#86c681'][i%3]}"/>`}
 let arc='';for(let i=0;i<=40;i++){const u=i/40,ang=Math.PI*u,x=2210-152*Math.cos(ang),y=1040+40*Math.sin(ang);arc+=`${i?'L':'M'}${r2(x)},${r2(y)} `}
 return svg('L',`<defs><linearGradient id="ixMd2" x1="0" y1="930" x2="0" y2="1200" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#c7edb3"/><stop offset=".5" stop-color="#b6e5a1"/><stop offset="1" stop-color="#a2da8f"/></linearGradient></defs>
<clipPath id="ixRoadCL"><path d="M2030,1040 L2058,1040 ${arc.replace(/^M/,'L')} L2362,1040 L2392,1040 L2392,1200 L2030,1200 Z"/></clipPath><g class="ix-lipfill"><path d="M2030,1040 L2058,1040 ${arc.replace(/^M/,'L')} L2362,1040 L2392,1040 L2392,1200 L2030,1200 Z" fill="url(#ixMd2)"/><g clip-path="url(#ixRoadCL)">${RD.body}</g></g>
<g class="ix-fringe">${fringe}<path d="${arc}" fill="none" stroke="#8a6750" stroke-width="3" opacity=".75"/>
</g>`)}
function flower(x,y,s,petal,centre,n){let p='';n=n||9;for(let i=0;i<n;i++){p+=`<ellipse cx="0" cy="-9" rx="4.2" ry="9" fill="${petal}" stroke="${INK}" stroke-opacity=".25" stroke-width=".8" transform="rotate(${r2(i*360/n)})"/>`}return `<g transform="translate(${r2(x)},${r2(y)}) scale(${r2(s)})">${p}<circle r="5" fill="${centre}"/></g>`}
function a1Front(){const R=rng(57);let out='',sway='';
 const cols=[['#ffffff','#f7c948'],['#ffd1e3','#f08bb0'],['#f7a8c4','#ffe08a'],['#e9dcff','#b08be8'],['#fff2b0','#f0a84e'],['#cfe7ff','#7fb3ef']];
 const skip=(x,y)=>(x>1960&&x<2420&&y<1110)||(y<1100&&y>1040&&x<2080);
 const lace=(x,y,s)=>{let u='';for(let i=0;i<16;i++){const a=R()*Math.PI*2,rr=Math.sqrt(R())*22;u+=`<circle cx="${r2(Math.cos(a)*rr*1.3)}" cy="${r2(Math.sin(a)*rr*.42)}" r="${r2(2.4+R()*1.6)}" fill="#fffef6" stroke="#e6dfc8" stroke-width=".7"/>`}
  return `<g transform="translate(${r2(x)},${r2(y)}) scale(${r2(s)})"><path d="M0,90 Q4,45 0,4" stroke="#86b97e" stroke-width="2.2" fill="none"/><path d="M0,4 L-18,-2 M0,4 L18,-2 M0,4 L0,-4 M0,4 L-9,-4 M0,4 L9,-4" stroke="#9cc88f" stroke-width="1.2"/>${u}</g>`};
 const bell=(x,y,s)=>{let b='';for(let i=0;i<4;i++){const bx=6+i*7,by=-6+i*9;b+=`<path d="M${bx},${by} c-6,1 -9,8 -8,13 c3,-2 5,-1 8,1 c3,-2 5,-3 8,-1 c1,-5 -2,-12 -8,-13 z" fill="${['#8fb0ef','#a3bff3','#7f9fe6'][i%3]}" stroke="#5f78bf" stroke-opacity=".5" stroke-width=".8"/>`}
  return `<g transform="translate(${r2(x)},${r2(y)}) scale(${r2(s)})"><path d="M0,70 Q-2,30 4,-4 Q14,-14 30,22" stroke="#7fb57a" stroke-width="2" fill="none"/>${b}</g>`};
 for(let i=0;i<92;i++){const x=R()*3200,y=1060+R()*140,s=.9+(y-1060)/140*1.3+R()*.4,c=cols[i%cols.length];if(skip(x,y))continue;
  const g=`<path d="M${r2(x)},${r2(y+40)} Q${r2(x+3)},${r2(y+20)} ${r2(x)},${r2(y)}" stroke="#7cbf7a" stroke-width="${r2(2*s)}" fill="none"/>${flower(x,y,s,c[0],c[1])}`;
  if(i%5===0)sway+=`<g class="ix-sway" style="animation-delay:${r2(-R()*3)}s">${g}</g>`;else out+=g}
 for(let i=0;i<30;i++){const x=R()*3200,y=1040+R()*130,s=.8+(y-1040)/130*.9;if(skip(x,y))continue;const g=lace(x,y,s);if(i%3===0)sway+=`<g class="ix-sway" style="animation-delay:${r2(-R()*3)}s">${g}</g>`;else out+=g}
 for(let i=0;i<34;i++){const x=R()*3200,y=1070+R()*120,s=.9+(y-1070)/120*.9;if(skip(x,y))continue;const g=bell(x,y,s);if(i%4===0)sway+=`<g class="ix-sway" style="animation-delay:${r2(-R()*3)}s">${g}</g>`;else out+=g}
 for(let i=0;i<60;i++){const x=R()*3200,y=1120+R()*90,h=30+R()*40;out+=`<path d="M${r2(x-6)},${r2(y+20)} Q${r2(x-3)},${r2(y-h*.4)} ${r2(x-10)},${r2(y-h)} Q${r2(x+2)},${r2(y-h*.45)} ${r2(x+5)},${r2(y+20)} Z" fill="${['#8fcf86','#a3da94','#7fc27c'][i%3]}"/>`}
 return svg('L',out+sway)}
function lorikeet(){return `<svg viewBox="0 0 120 80" width="120" height="80" aria-hidden="true"><g class="ix-wingb"><path d="M54,34 C46,12 30,4 14,6 C28,14 38,24 46,38 Z" fill="#3aa865" stroke="#2a6f4b" stroke-width="1.4"/></g>
<path d="M4,50 L-10,60 L20,52 Z" fill="#2f9e5c" stroke="#2a6f4b" stroke-width="1.2"/><path d="M16,46 C32,34 58,30 78,34 C90,36 98,42 100,48 C92,55 72,58 54,56 C42,55 28,52 16,46 Z" fill="#45c274" stroke="#2a6f4b" stroke-width="1.4"/>
<path d="M64,44 C72,40 86,42 92,48 C84,54 72,54 64,50 Z" fill="#ff8f3f"/><path d="M86,44 C90,48 95,49 99,48" stroke="#ffd24d" stroke-width="3.4" fill="none" stroke-linecap="round"/>
<circle cx="96" cy="38" r="12" fill="#4e63e2" stroke="#2c3a99" stroke-width="1.4"/><path d="M106,36 C114,37 115,43 109,46 C107,42 105,40 106,36 Z" fill="#ff5a36" stroke="#b5321c" stroke-width="1"/><circle cx="99" cy="35" r="2.6" fill="#24183a"/><circle cx="99.8" cy="34.2" r=".9" fill="#fff"/>
<g class="ix-wingf"><path d="M62,36 C56,8 34,-4 14,0 C30,10 44,24 52,40 Z" fill="#55d585" stroke="#2a6f4b" stroke-width="1.4"/><path d="M16,1 C26,5 32,9 38,15" stroke="#4e63e2" stroke-width="4" fill="none" stroke-linecap="round"/></g></svg>`}

/* ---------------- ACT 2: the rabbit hole walls (seamless tiles) ---------------- */
const PAL=['#c9b6f2','#f7a8c4','#9fe0c8','#ffc4a6','#9fd0f5','#f7d774','#e3d4ff','#ffd6e7'];
function books(x,y,w,h,R){let s='',cx=x+10;while(cx<x+w-26){const bw=18+R()*18,bh=h*(.62+R()*.34),col=PAL[Math.floor(R()*PAL.length)],lean=R()<.12;
  const g=`<rect x="${r2(cx)}" y="${r2(y+h-bh)}" width="${r2(bw)}" height="${r2(bh)}" rx="3" fill="${col}" stroke="${INK}" stroke-opacity=".55" stroke-width="1.6"/><rect x="${r2(cx)}" y="${r2(y+h-bh+10)}" width="${r2(bw)}" height="4" fill="${GOLD}" opacity=".85"/><rect x="${r2(cx)}" y="${r2(y+h-14)}" width="${r2(bw)}" height="4" fill="${GOLD}" opacity=".85"/>`;
  s+=lean?`<g transform="rotate(-12 ${r2(cx+bw)} ${r2(y+h)})">${g}</g>`:g;cx+=bw+(lean?14:2)}return s}
function shelf(x,y,w,h,R){return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12" fill="#ecd2b2" stroke="${INK}" stroke-opacity=".6" stroke-width="2.2"/><rect x="${x+12}" y="${y+12}" width="${w-24}" height="${h-24}" rx="6" fill="#d9b897"/>`+books(x+12,y+14,w-24,h/2-20,R)+`<rect x="${x+8}" y="${y+h/2-8}" width="${w-16}" height="12" rx="3" fill="#f3dcbf" stroke="${INK}" stroke-opacity=".5" stroke-width="1.6"/>`+books(x+12,y+h/2+6,w-24,h/2-26,R)+`<rect x="${x+8}" y="${y+h-20}" width="${w-16}" height="12" rx="3" fill="#f3dcbf" stroke="${INK}" stroke-opacity=".5" stroke-width="1.6"/>`}
function cupboard(x,y,w,h,R){const c=PAL[Math.floor(R()*PAL.length)],ajar=R()<.4;return `<rect x="${x}" y="${y+18}" width="${w}" height="${h-18}" rx="10" fill="${c}" stroke="${INK}" stroke-opacity=".6" stroke-width="2.2"/><rect x="${x-10}" y="${y}" width="${w+20}" height="24" rx="6" fill="#fff4e6" stroke="${INK}" stroke-opacity=".5" stroke-width="1.8"/>
<rect x="${x+16}" y="${y+38}" width="${w/2-24}" height="${h-72}" rx="8" fill="#fff" opacity=".35" stroke="${INK}" stroke-opacity=".4" stroke-width="1.6"/>`+(ajar?`<rect x="${x+w/2+8}" y="${y+38}" width="${w/2-24}" height="${h-72}" rx="6" fill="#4a3657"/><path d="M${x+w/2+8},${y+38} L${x+w-6},${y+50} L${x+w-6},${y+h-46} L${x+w/2+8},${y+h-34} Z" fill="#fff" opacity=".55" stroke="${INK}" stroke-opacity=".45" stroke-width="1.6"/><circle cx="${x+w/2+40}" cy="${y+h/2}" r="10" fill="${GOLD2}"/>`:`<rect x="${x+w/2+8}" y="${y+38}" width="${w/2-24}" height="${h-72}" rx="8" fill="#fff" opacity=".35" stroke="${INK}" stroke-opacity=".4" stroke-width="1.6"/>`)+`<circle cx="${x+w/2-14}" cy="${y+h/2}" r="8" fill="${GOLD}" stroke="#a7792b" stroke-width="1.5"/><circle cx="${x+w/2+14}" cy="${y+h/2}" r="8" fill="${GOLD}" stroke="#a7792b" stroke-width="1.5"/><rect x="${x+12}" y="${y+h-6}" width="16" height="14" fill="#c9a37f"/><rect x="${x+w-28}" y="${y+h-6}" width="16" height="14" fill="#c9a37f"/>`}
function mapPeg(x,y,w,h,R){const rot=r2(-6+R()*12),cx=x+w/2,mw=w*.86,mh=h*.72,mx=cx-mw/2,my=y+42;return `<circle cx="${cx}" cy="${y+14}" r="9" fill="${GOLD}" stroke="#a7792b" stroke-width="1.5"/><path d="M${cx},${y+14} L${mx+20},${my+4} M${cx},${y+14} L${mx+mw-20},${my+4}" stroke="#a88c6a" stroke-width="2"/>
<g transform="rotate(${rot} ${cx} ${my+mh/2})"><rect x="${mx}" y="${my}" width="${mw}" height="${mh}" rx="6" fill="#fff6e2" stroke="#c9a978" stroke-width="2.4"/><rect x="${mx+10}" y="${my+10}" width="${mw-20}" height="${mh-20}" rx="4" fill="#dff1fb"/>
<path d="M${mx+30},${my+mh*.3} C${mx+mw*.3},${my+mh*.15} ${mx+mw*.45},${my+mh*.35} ${mx+mw*.55},${my+mh*.3} C${mx+mw*.7},${my+mh*.22} ${mx+mw*.8},${my+mh*.5} ${mx+mw*.68},${my+mh*.7} C${mx+mw*.5},${my+mh*.88} ${mx+mw*.3},${my+mh*.78} ${mx+mw*.22},${my+mh*.62} C${mx+mw*.12},${my+mh*.5} ${mx+20},${my+mh*.45} ${mx+30},${my+mh*.3} Z" fill="#cdeec6" stroke="#7fb08a" stroke-width="2"/>
<path d="M${mx+mw*.3},${my+mh*.55} C${mx+mw*.4},${my+mh*.45} ${mx+mw*.5},${my+mh*.62} ${mx+mw*.6},${my+mh*.48}" fill="none" stroke="#e0567c" stroke-width="2.6" stroke-dasharray="6 6"/><path d="M${mx+mw*.6-8},${my+mh*.48-8} l16,16 m0,-16 l-16,16" stroke="#e0567c" stroke-width="3"/>
<g transform="translate(${mx+mw-34},${my+34})"><circle r="16" fill="#fff" stroke="#c9a978" stroke-width="1.6"/><path d="M0,-14 L4,0 L0,14 L-4,0 Z" fill="#e0567c"/><path d="M-14,0 L0,-4 L14,0 L0,4 Z" fill="#7a4fc4" opacity=".7"/></g></g>`}
function frameOval(x,y,w,h){const cx=x+w/2,cy=y+h/2,rx=w*.38,ry=h*.42;return `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="url(#ixFrSky)"/><path d="M${cx-rx},${cy+ry*.15} C${cx-rx*.4},${cy-ry*.25} ${cx},${cy+ry*.3} ${cx+rx},${cy-ry*.05} A${rx},${ry} 0 0 1 ${cx-rx},${cy+ry*.15} Z" fill="#b9e3b4"/><circle cx="${cx+rx*.35}" cy="${cy-ry*.35}" r="${rx*.14}" fill="#fff3bf"/><ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="none" stroke="${GOLD}" stroke-width="16"/><ellipse cx="${cx}" cy="${cy}" rx="${rx+9}" ry="${ry+9}" fill="none" stroke="#a7792b" stroke-width="2"/><ellipse cx="${cx}" cy="${cy}" rx="${rx-9}" ry="${ry-9}" fill="none" stroke="#fff3c9" stroke-width="2"/>`}
function sconce(x,y){return `<circle cx="${x}" cy="${y-30}" r="90" fill="url(#ixGlow)"/><path d="M${x-26},${y+30} C${x-26},${y+6} ${x+26},${y+6} ${x+26},${y+30} Z" fill="${GOLD}" stroke="#a7792b" stroke-width="2"/><rect x="${x-9}" y="${y-36}" width="18" height="44" rx="4" fill="#fffaf0" stroke="${INK}" stroke-opacity=".4" stroke-width="1.6"/><path d="M${x},${y-66} C${x+9},${y-52} ${x+7},${y-42} ${x},${y-38} C${x-7},${y-42} ${x-9},${y-52} ${x},${y-66} Z" fill="#ffcf5a" stroke="#f39a2e" stroke-width="1.4"/>`}
function clockFace(x,y,r){let t='';for(let i=0;i<12;i++){const a=i/12*Math.PI*2;t+=`<line x1="${r2(x+Math.cos(a)*(r-6))}" y1="${r2(y+Math.sin(a)*(r-6))}" x2="${r2(x+Math.cos(a)*(r-16))}" y2="${r2(y+Math.sin(a)*(r-16))}" stroke="${INK}" stroke-width="3" stroke-linecap="round"/>`}return `<circle cx="${x}" cy="${y}" r="${r+12}" fill="${GOLD}" stroke="#a7792b" stroke-width="2"/><circle cx="${x}" cy="${y}" r="${r}" fill="#fffaf0"/>${t}<line x1="${x}" y1="${y}" x2="${x}" y2="${y-r*.6}" stroke="${INK}" stroke-width="5" stroke-linecap="round"/><line x1="${x}" y1="${y}" x2="${x+r*.45}" y2="${y+r*.2}" stroke="#e0567c" stroke-width="4" stroke-linecap="round"/><circle cx="${x}" cy="${y}" r="6" fill="${INK}"/>`}
function jarShelf(x,y,w,R){let s=`<rect x="${x}" y="${y+120}" width="${w}" height="16" rx="4" fill="#f3dcbf" stroke="${INK}" stroke-opacity=".55" stroke-width="1.8"/><path d="M${x+20},${y+136} L${x+40},${y+170} M${x+w-20},${y+136} L${x+w-40},${y+170}" stroke="#c9a37f" stroke-width="6"/>`;let cx=x+24;const jc=['#ffa94d','#f06fa0','#f7c948','#a98bea'];while(cx<x+w-70){const c=jc[Math.floor(R()*4)];s+=`<rect x="${cx}" y="${y+46}" width="56" height="74" rx="12" fill="${c}" opacity=".85" stroke="${INK}" stroke-opacity=".5" stroke-width="1.8"/><rect x="${cx+4}" y="${y+50}" width="10" height="56" rx="5" fill="#fff" opacity=".55"/><rect x="${cx-3}" y="${y+34}" width="62" height="16" rx="5" fill="#fff" stroke="${INK}" stroke-opacity=".4" stroke-width="1.4"/><rect x="${cx+10}" y="${y+70}" width="36" height="22" rx="3" fill="#fffaf0"/>`;cx+=74+R()*14}return s}
